function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each value is a whole number from -1000 to 1000.';
  if (nums.includes(0)) return 'nums may not contain 0.';
  return null;
}

