function findMaxK(nums) {
  // Compare every pair of positions and keep the largest positive value whose negative was found.
  let answer = -1;
  for (let i = 0; i < nums.length; i++) {
    for (let j = 0; j < nums.length; j++) {
      if (nums[i] > 0 && nums[j] === -nums[i]) answer = Math.max(answer, nums[i]);
    }
  }
  return answer;
}

