function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 10);
  const span = size === 'large' ? 1000 : (rand() < 0.5 ? 4 : 1000);
  const mode = rand();
  const nums = [];
  for (let i = 0; i < n; i++) {
    const magnitude = 1 + Math.floor(rand() * span);
    // Sometimes keep every value positive, or give each magnitude one fixed sign, so no pair exists.
    let sign = rand() < 0.5 ? -1 : 1;
    if (mode < 0.15) sign = 1;
    else if (mode < 0.3) sign = magnitude % 2 === 0 ? 1 : -1;
    nums.push(sign * magnitude);
  }
  return [nums];
}
